$mine = @(); foreach ($c in $cats.Keys) { $mine += @($cats[$c].Keys) }
$taken = @{}; $tt.specific.PSObject.Properties | ? { $mine -notcontains $_.Name } | % { $_.Value | ? { $_ } | % { $taken[(& $slug $_)] = 1 } }
$final = @{}
foreach ($c in $cats.Keys) {
  $kinds = @($cats[$c].Keys)
  if ($tt.subjects.PSObject.Properties[$c]) { $tt.subjects.$c = $kinds } else { $tt.subjects | Add-Member -NotePropertyName $c -NotePropertyValue $kinds }
  foreach ($k in $kinds) {
    $names = @($cats[$c][$k] | % { $o = $_; if ($taken.ContainsKey((& $slug $o))) { $nn = $o + " in " + $c + " Style"; "  RENAMED: " + $nn | Out-Host } else { $nn = $o }; $final[$o] = $nn; $nn })
    if ($tt.specific.PSObject.Properties[$k]) { $tt.specific.$k = $names } else { $tt.specific | Add-Member -NotePropertyName $k -NotePropertyValue $names }
  }
}
$json = $tt | ConvertTo-Json -Depth 20 -Compress
$check = $json | ConvertFrom-Json
$afterCats = @($check.subjects.PSObject.Properties).Count
if ($afterCats -lt $beforeCats -or $json.Length -lt ($got.raw.Length * 0.9)) { "  SAFETY STOP - the new catalog looks smaller than the old one, nothing written" } else {
$tmp = Join-Path $env:TEMP "card-tree-new.json"
[System.IO.File]::WriteAllText($tmp, $json, (New-Object System.Text.UTF8Encoding $false))
npx wrangler kv key put --namespace-id $ns "card:tree" --path $tmp --remote 2>$null | Out-Null
"  catalog written in ONE save: " + $beforeCats + " categories before, " + $afterCats + " after"
"  saving the split-card settings and the 200 tattoo descriptions..."
$n = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) {
  $ks = & $slug $k
  RUN ("SETKV render:" + $ks + " Two panels side by side on one image, divided down the middle. LEFT PANEL: the tattoo design alone on a plain white background, shown flat exactly as described, no body, drawn large so it fills most of the panel. RIGHT PANEL: Studio photograph of a real person's body showing the same exact tattoo where described, healed tattoo on real skin in soft even light, the rest of the body modestly covered by simple plain clothing, only the tattooed area bare, plain seamless light grey studio backdrop - no room, no furniture, no scenery. The tattoo in both panels is identical.") | Out-Null
  RUN ("SETKV shape:" + $ks + " 3:2") | Out-Null
  RUN ("SETKV split:" + $ks + " yes") | Out-Null
  foreach ($o in $cats[$c][$k]) { RUN ("SETKV build:" + (& $slug $final[$o]) + " " + $b[$o]) | Out-Null; $n++ }
} }
"  " + $n + " descriptions saved - waiting 70 seconds so every server sees the new catalog..."
Start-Sleep -Seconds 70
$got2 = Read-Tree
$short = 0
foreach ($c in $cats.Keys) { foreach ($k in $cats[$c].Keys) { $h = @($got2.tree.specific.$k | ? { $_ }).Count; if ($h -ne $cats[$c][$k].Count) { "  STILL SHORT: " + $k + " has " + $h; $short++ } } }
if ($short) { "== " + $short + " sets short - send me this output ==" } else {
"== Geometric, Abstract, Witchy, Western, Fun saved - the test cards: =="
"== removing any old style words sitting on these new sets =="
$want = @('context:abstract-art','context:abstract-color-as-subject','context:abstract-gallery-pieces','context:abstract-gesture-and-brushstroke','context:abstract-ink-and-splatter','context:abstract-minimal','context:abstract-organic-forms','context:abstract-partial-recognition','context:abstract-scribble','context:abstract-texture-and-material','context:abstract-torn-and-collage','context:fun','context:fun-animals-having-a-life','context:fun-cute-not-babyish','context:fun-everyday-life-better','context:fun-food-gone-wrong','context:fun-little-adventures','context:fun-party-night-out','context:fun-push-it','context:fun-skeletons-having-fun','context:geometric-3d-dimensional','context:geometric-and-patterns','context:geometric-animals','context:geometric-architectural','context:geometric-breaking-the-grid','context:geometric-optical-illusions','context:geometric-pattern-and-texture','context:geometric-plus-nature','context:geometric-pure-pattern','context:geometric-sacred-and-cosmic','context:geometric-weird-experimental','context:western','context:western-cowboys','context:western-cowgirls','context:western-desert-and-honky-tonk','context:western-goes-anywhere','context:western-objects','context:western-outlaws-and-gothic','context:western-rodeo-and-ranch','context:western-weird-west','context:witchy-and-occult','context:witchy-black-cats-and-familiars','context:witchy-candles-and-ritual-light','context:witchy-crystal-balls','context:witchy-fun-and-modern','context:witchy-night-creatures','context:witchy-potions-and-alchemy','context:witchy-seance-and-spirits','context:witchy-spell-books','context:witchy-tarot','context:witchy-witches')
$have = @((npx wrangler kv key list --namespace-id $ns --prefix "context:" --remote 2>$null | Out-String | ConvertFrom-Json) | % { $_.name })
$hit = @($have | ? { $want -contains $_ })
if ($hit.Count -eq 0) { "  none found" } else { foreach ($h in $hit) { "  removed " + $h + ": " + ((npx wrangler kv key get --namespace-id $ns $h --remote 2>$null | Out-String).Trim()); npx wrangler kv key delete --namespace-id $ns $h --remote 2>$null | Out-Null } }
foreach ($c in $cats.Keys) { RUN ("REDO " + $final[$test[$c]]) }
}
}
